DROP TABLE IF EXISTS `endereco`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `endereco` (
  `cep` varchar(9) NOT NULL,
  `num_end` int NOT NULL,
  `rua` varchar(100) DEFAULT NULL,
  `bairro` varchar(50) DEFAULT NULL,
  `cidade` varchar(50) DEFAULT NULL,
  `estado` varchar(2) DEFAULT NULL,
  `entregador_id_entregador` int DEFAULT NULL,
  `restaurante_id_restaurante` int DEFAULT NULL,
  PRIMARY KEY (`cep`,`num_end`),
  KEY `fk_endereco_entregador_idx` (`entregador_id_entregador`),
  KEY `fk_endereco_restaurante1_idx` (`restaurante_id_restaurante`),
  CONSTRAINT `fk_endereco_entregador` FOREIGN KEY (`entregador_id_entregador`) REFERENCES `entregador` (`id_entregador`),
  CONSTRAINT `fk_endereco_restaurante1` FOREIGN KEY (`restaurante_id_restaurante`) REFERENCES `restaurante` (`id_restaurante`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
