--
-- Table structure for table `telefone`
--

DROP TABLE IF EXISTS `telefone`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `telefone` (
  `num_tel` varchar(20) NOT NULL,
  `entregador_id_entregador` int DEFAULT NULL,
  `restaurante_id_restaurante` int DEFAULT NULL,
  `cliente_id_cliente` int DEFAULT NULL,
  PRIMARY KEY (`num_tel`),
  KEY `fk_telefone_entregador1_idx` (`entregador_id_entregador`),
  KEY `fk_telefone_restaurante1_idx` (`restaurante_id_restaurante`),
  KEY `fk_telefone_cliente1_idx` (`cliente_id_cliente`),
  CONSTRAINT `fk_telefone_cliente1` FOREIGN KEY (`cliente_id_cliente`) REFERENCES `cliente` (`id_cliente`),
  CONSTRAINT `fk_telefone_entregador1` FOREIGN KEY (`entregador_id_entregador`) REFERENCES `entregador` (`id_entregador`),
  CONSTRAINT `fk_telefone_restaurante1` FOREIGN KEY (`restaurante_id_restaurante`) REFERENCES `restaurante` (`id_restaurante`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

